<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import api from '../services/api'

const suppliers=ref([]), products=ref([]), branches=ref([]), orders=ref([]), invoices=ref([]), payments=ref([]), report=ref(null), error=ref('')
const tab=ref('invoices'), showSupplier=ref(false), showOrder=ref(false), showInvoice=ref(false), showPayment=ref(false), selected=ref(null)
const supplier=reactive({name:'',mobile:'',contact_person:'',credit_limit:''})
const order=reactive({branch_id:'',supplier_id:'',document_date:'',discount:0,vat:0,notes:'',items:[{product_id:'',quantity:1,unit_cost:''}]})
const invoice=reactive({branch_id:'',supplier_id:'',document_date:'',supplier_invoice_number:'',discount:0,vat:0,paid_amount:0,notes:'',items:[{product_id:'',quantity:1,unit_cost:''}]})
const payment=reactive({branch_id:'',supplier_id:'',amount:'',method:'cash',transaction_id:'',notes:''})
const apiData = r => r.data.data?.data ?? r.data.data ?? []
const load=async()=>{try{const [s,p,b,o,i,sp,pr]=await Promise.all([api.get('/suppliers'),api.get('/products'),api.get('/businesses'),api.get('/purchase-orders'),api.get('/purchase-invoices'),api.get('/supplier-payments'),api.get('/reports/purchases')]);suppliers.value=apiData(s);products.value=apiData(p);const business=apiData(b)[0];branches.value=business?apiData(await api.get(`/businesses/${business.id}/branches`)):[];orders.value=apiData(o);invoices.value=apiData(i);payments.value=apiData(sp);report.value=pr.data.data;if(branches.value.length){if(!order.branch_id)order.branch_id=branches.value[0].id;if(!invoice.branch_id)invoice.branch_id=branches.value[0].id;if(!payment.branch_id)payment.branch_id=branches.value[0].id}}catch(e){error.value=e.response?.data?.message||'তথ্য লোড করা যায়নি।'}}
const addItem=f=>f.items.push({product_id:'',quantity:1,unit_cost:''}); const removeItem=(f,index)=>f.items.length>1&&f.items.splice(index,1)
const total=f=>f.items.reduce((sum,item)=>sum+(Number(item.quantity||0)*Number(item.unit_cost||productCost(item.product_id))),0)-Number(f.discount||0)+Number(f.vat||0)
const productCost=id=>products.value.find(p=>p.id===Number(id))?.purchase_price||0
const reset=(target,base)=>Object.assign(target,base)
const saveSupplier=async()=>{try{await api.post('/suppliers',supplier);showSupplier.value=false;reset(supplier,{name:'',mobile:'',contact_person:'',credit_limit:''});load()}catch(e){error.value=e.response?.data?.message||'সরবরাহকারী সংরক্ষণ করা যায়নি।'}}
const saveOrder=async()=>{try{await api.post('/purchase-orders',order);showOrder.value=false;reset(order,{branch_id:branches.value[0]?.id||'',supplier_id:'',document_date:'',discount:0,vat:0,notes:'',items:[{product_id:'',quantity:1,unit_cost:''}]});load()}catch(e){error.value=e.response?.data?.message||'অর্ডার সংরক্ষণ করা যায়নি।'}}
const saveInvoice=async()=>{try{await api.post('/purchase-invoices',invoice);showInvoice.value=false;reset(invoice,{branch_id:branches.value[0]?.id||'',supplier_id:'',document_date:'',supplier_invoice_number:'',discount:0,vat:0,paid_amount:0,notes:'',items:[{product_id:'',quantity:1,unit_cost:''}]});load()}catch(e){error.value=e.response?.data?.message||'ক্রয় ইনভয়েস সংরক্ষণ করা যায়নি।'}}
const receive=async row=>{if(!confirm(`ক্রয় ইনভয়েস ${row.invoice_number} গ্রহণ করে স্টকে যোগ করবেন?`))return;try{await api.post(`/purchase-invoices/${row.id}/receive`);load()}catch(e){error.value=e.response?.data?.message||'স্টক গ্রহণ করা যায়নি।'}}
const savePayment=async()=>{try{await api.post('/supplier-payments',payment);showPayment.value=false;reset(payment,{branch_id:branches.value[0]?.id||'',supplier_id:'',amount:'',method:'cash',transaction_id:'',notes:''});load()}catch(e){error.value=e.response?.data?.message||'পেমেন্ট সংরক্ষণ করা যায়নি।'}}
const showLedger=async row=>{try{selected.value=(await api.get(`/suppliers/${row.id}/ledger`)).data.data}catch(e){error.value=e.response?.data?.message||'লেজার লোড করা যায়নি।'}}
const createReturn=async row=>{if(!row.items?.length)return;const menu=row.items.map((item,index)=>`${index+1}. ${item.product_name} (${item.quantity})`).join('\n');const choice=Number(prompt(`ফেরত পণ্য নম্বর লিখুন:\n${menu}`,'1'))-1;const item=row.items[choice];if(!item)return;const quantity=prompt(`ফেরত পরিমাণ (${item.product_name})`,'1');if(!quantity)return;try{await api.post(`/purchase-invoices/${row.id}/returns`,{items:[{product_id:item.product_id,quantity:Number(quantity)}]});load()}catch(e){error.value=e.response?.data?.message||'রিটার্ন করা যায়নি।'}}
const pending=computed(()=>invoices.value.filter(i=>i.status==='draft'))
const doc=computed(()=>showOrder.value?order:invoice)
onMounted(load)
</script>

<template><section>
  <div class="page-heading inline"><div><p class="eyebrow">PURCHASING & SUPPLIERS</p><h2>ক্রয় ও সরবরাহকারী</h2><p>ক্রয়, স্টক গ্রহণ, সরবরাহকারী বাকি ও পেমেন্ট পরিচালনা করুন।</p></div><div class="button-row"><button class="secondary" @click="showSupplier=true">+ সরবরাহকারী</button><button class="secondary" @click="showOrder=true">+ ক্রয় অর্ডার</button><button class="primary" @click="showInvoice=true">+ ক্রয় ইনভয়েস</button></div></div>
  <p v-if="error" class="error">{{error}}</p>
  <div class="tabs"><button v-for="t in [['invoices','ক্রয় ইনভয়েস'],['orders','ক্রয় অর্ডার'],['suppliers','সরবরাহকারী'],['payments','সরবরাহকারী পেমেন্ট'],['reports','ক্রয় রিপোর্ট']]" :key="t[0]" :class="{active:tab===t[0]}" @click="tab=t[0]">{{t[1]}}</button></div>
  <div v-if="showSupplier" class="page-card compact"><form class="form-grid" @submit.prevent="saveSupplier"><label>নাম<input v-model="supplier.name" required /></label><label>মোবাইল<input v-model="supplier.mobile" /></label><label>যোগাযোগ ব্যক্তি<input v-model="supplier.contact_person" /></label><label>ক্রেডিট সীমা<input v-model.number="supplier.credit_limit" type="number" min="0" /></label><div class="full-width form-actions"><button type="button" class="secondary" @click="showSupplier=false">বাতিল</button><button class="primary">সংরক্ষণ</button></div></form></div>
  <div v-if="showOrder || showInvoice" class="page-card compact"><form class="form-grid" @submit.prevent="showOrder?saveOrder():saveInvoice()"><label>শাখা<select v-model="doc.branch_id" required><option v-for="b in branches" :value="b.id">{{b.name}}</option></select></label><label>সরবরাহকারী<select v-model="doc.supplier_id" required><option value="">নির্বাচন করুন</option><option v-for="s in suppliers" :value="s.id">{{s.name}}</option></select></label><label>তারিখ<input v-model="doc.document_date" type="date" /></label><label v-if="showInvoice">সরবরাহকারী ইনভয়েস<input v-model="invoice.supplier_invoice_number" /></label><div class="full-width"><strong>পণ্যসমূহ</strong><div v-for="(item,index) in doc.items" :key="index" class="line-item"><select v-model="item.product_id" required><option value="">পণ্য নির্বাচন করুন</option><option v-for="p in products" :value="p.id">{{p.name}} · ৳{{p.purchase_price}}</option></select><input v-model.number="item.quantity" type="number" min="0.001" step="0.001" placeholder="পরিমাণ" required /><input v-model.number="item.unit_cost" type="number" min="0" step="0.01" :placeholder="`মূল্য: ${productCost(item.product_id)}`" /><button type="button" class="icon-button" @click="removeItem(doc,index)">×</button></div><button type="button" class="text-button" @click="addItem(doc)">+ আরও পণ্য</button></div><label>ছাড়<input v-model.number="doc.discount" type="number" min="0" /></label><label>VAT<input v-model.number="doc.vat" type="number" min="0" /></label><label v-if="showInvoice">প্রদত্ত টাকা<input v-model.number="invoice.paid_amount" type="number" min="0" /></label><label>মোট<strong>৳{{total(doc).toFixed(2)}}</strong></label><div class="full-width form-actions"><button type="button" class="secondary" @click="showOrder=false;showInvoice=false">বাতিল</button><button class="primary">{{showOrder?'অর্ডার সংরক্ষণ':'ইনভয়েস সংরক্ষণ'}}</button></div></form></div>
  <div v-if="tab==='invoices'" class="table-card"><div class="table-title"><strong>ক্রয় ইনভয়েস</strong><small>{{pending.length}} টি স্টক গ্রহণ বাকি</small></div><table><thead><tr><th>ইনভয়েস</th><th>সরবরাহকারী</th><th>তারিখ</th><th>মোট</th><th>স্ট্যাটাস</th><th></th></tr></thead><tbody><tr v-for="i in invoices" :key="i.id"><td>{{i.invoice_number}}</td><td>{{i.supplier?.name}}</td><td>{{i.invoice_date}}</td><td>৳{{i.grand_total}}</td><td><span class="role-chip">{{i.status}}</span></td><td class="actions"><button v-if="i.status==='draft'" class="primary small" @click="receive(i)">স্টক গ্রহণ</button><button v-if="i.status==='received'" class="secondary small" @click="createReturn(i)">রিটার্ন</button></td></tr></tbody></table></div>
  <div v-if="tab==='orders'" class="table-card"><table><thead><tr><th>অর্ডার</th><th>সরবরাহকারী</th><th>শাখা</th><th>তারিখ</th><th>মোট</th><th>অবস্থা</th></tr></thead><tbody><tr v-for="o in orders" :key="o.id"><td>{{o.order_number}}</td><td>{{o.supplier?.name}}</td><td>{{o.branch?.name}}</td><td>{{o.order_date}}</td><td>৳{{o.grand_total}}</td><td><span class="role-chip">{{o.status}}</span></td></tr><tr v-if="!orders.length"><td colspan="6" class="empty">কোনো ক্রয় অর্ডার নেই।</td></tr></tbody></table></div>
  <div v-if="tab==='suppliers'" class="table-card"><table><thead><tr><th>সরবরাহকারী</th><th>মোবাইল</th><th>ক্রেডিট সীমা</th><th>বর্তমান বাকি</th><th></th></tr></thead><tbody><tr v-for="s in suppliers" :key="s.id"><td>{{s.name}}</td><td>{{s.mobile||'—'}}</td><td>৳{{s.credit_limit}}</td><td><strong>৳{{s.current_due}}</strong></td><td><button class="secondary small" @click="showLedger(s)">লেজার</button></td></tr></tbody></table></div>
  <div v-if="tab==='payments'"><div class="button-row right"><button class="primary" @click="showPayment=true">+ পেমেন্ট দিন</button></div><div v-if="showPayment" class="page-card compact"><form class="form-grid" @submit.prevent="savePayment"><label>সরবরাহকারী<select v-model="payment.supplier_id" required><option value="">নির্বাচন করুন</option><option v-for="s in suppliers" :value="s.id">{{s.name}} · বাকি ৳{{s.current_due}}</option></select></label><label>শাখা<select v-model="payment.branch_id" required><option v-for="b in branches" :value="b.id">{{b.name}}</option></select></label><label>পরিমাণ<input v-model.number="payment.amount" type="number" min="1" required /></label><label>মাধ্যম<select v-model="payment.method"><option value="cash">Cash</option><option value="bank">Bank</option><option value="bkash">bKash</option><option value="nagad">Nagad</option></select></label><label v-if="payment.method!=='cash'">Transaction ID<input v-model="payment.transaction_id" required /></label><div class="full-width form-actions"><button type="button" class="secondary" @click="showPayment=false">বাতিল</button><button class="primary">পেমেন্ট সংরক্ষণ</button></div></form></div><div class="table-card"><table><thead><tr><th>রসিদ</th><th>সরবরাহকারী</th><th>তারিখ</th><th>মাধ্যম</th><th>পরিমাণ</th></tr></thead><tbody><tr v-for="p in payments" :key="p.id"><td>{{p.receipt_number}}</td><td>{{p.supplier?.name}}</td><td>{{p.payment_date}}</td><td>{{p.method}}</td><td>৳{{p.amount}}</td></tr></tbody></table></div></div>
  <div v-if="tab==='reports' && report" class="metric-grid"><article class="metric-card"><small>ক্রয়</small><strong>৳{{report.purchase_total}}</strong></article><article class="metric-card"><small>সরবরাহকারী বাকি</small><strong>৳{{report.supplier_due}}</strong></article><article class="metric-card"><small>পেমেন্ট</small><strong>৳{{report.payments}}</strong></article><article class="metric-card"><small>রিটার্ন</small><strong>৳{{report.returns}}</strong></article><div class="table-card full-width"><table><thead><tr><th>সরবরাহকারী</th><th>ক্রয়</th></tr></thead><tbody><tr v-for="row in report.by_supplier" :key="row.supplier_id"><td>{{row.supplier?.name}}</td><td>৳{{row.total}}</td></tr></tbody></table></div></div>
  <div v-if="selected" class="modal-backdrop" @click.self="selected=null"><div class="modal"><button class="icon-button close" @click="selected=null">×</button><h3>{{selected.supplier.name}} — লেজার</h3><table><thead><tr><th>তারিখ</th><th>ধরন</th><th>রেফারেন্স</th><th>ডেবিট</th><th>ক্রেডিট</th><th>ব্যালেন্স</th></tr></thead><tbody><tr v-for="l in selected.entries.data" :key="l.id"><td>{{l.entry_date}}</td><td>{{l.type}}</td><td>{{l.reference}}</td><td>{{l.debit}}</td><td>{{l.credit}}</td><td>{{l.balance}}</td></tr></tbody></table></div></div>
</section></template>
